
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_pc07_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_pc07", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.439417119089030e+01, 2.434649686400661e+01, 2.427631606941563e+01, 2.417289541882846e+01, 2.402101583916856e+01, 2.380004617695145e+01, 2.348161848287763e+01, 2.336937504540074e+01, 2.407136234853973e+01, 2.361778394735524e+01, 1.887140771679527e+01, 5.972633576877954e+00, 1.310771419573195e+00, 1.244028238648154e+00, 1.096489115597148e+00, 9.338843895521600e-01, 8.723199933350824e-01, 9.648831915405587e-01, 6.623855573223886e-01, 5.750019933740846e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


